let Window = 15m;
let FailedSignInThreshold = 8;
let DistinctAccountThreshold = 3;
let FailedSignIns =
    SigninLogs
    | where TimeGenerated {TimeRange:query}
    | where tostring(ResultType) != '0'
    | extend AccountName = tostring(UserPrincipalName)
    | where isnotempty(AccountName) and isnotempty(IPAddress)
    | summarize FailureCount = count(), DistinctAccounts = dcount(AccountName), FirstFailureTime = min(TimeGenerated), LastFailureTime = max(TimeGenerated) by IPAddress, TimeWindow = bin(TimeGenerated, Window);
let SuccessfulSignIns =
    SigninLogs
    | where TimeGenerated {TimeRange:query}
    | where tostring(ResultType) == '0'
    | extend AccountName = tostring(UserPrincipalName)
    | where isnotempty(AccountName) and isnotempty(IPAddress)
    | project SuccessTime = TimeGenerated, AccountName, IPAddress, AppDisplayName = tostring(AppDisplayName);
FailedSignIns
| where FailureCount >= FailedSignInThreshold and DistinctAccounts >= DistinctAccountThreshold
| join kind=inner SuccessfulSignIns on IPAddress
| where SuccessTime between (LastFailureTime .. (LastFailureTime + Window))
| extend TimeGenerated = SuccessTime, Action = strcat('Failed sign-ins against ', tostring(DistinctAccounts), ' accounts followed by success. App=', AppDisplayName), Severity = case(FailureCount >= 25 or DistinctAccounts >= 8, 'High', 'Medium')
| project TimeGenerated, AccountName, IPAddress, Action, Severity, FailureCount, DistinctAccounts, AppDisplayName
| order by TimeGenerated desc

let Window = 15m;
let SecretOperationThreshold = 20;
let VaultThreshold = 2;
let SensitiveOperations = dynamic(['SecretGet', 'SecretList', 'SecretBackup', 'KeyGet', 'KeyList', 'KeyBackup', 'CertificateGet', 'CertificateList', 'CertificateBackup', 'secrets/read', 'secrets/list', 'secrets/backup', 'keys/read', 'keys/list', 'keys/backup', 'certificates/read', 'certificates/list', 'certificates/backup']);
let VaultDiagnosticEvents =
    AzureDiagnostics
    | where TimeGenerated {TimeRange:query}
    | where tostring(column_ifexists('ResourceProvider', '')) =~ 'MICROSOFT.KEYVAULT' or tostring(column_ifexists('ResourceProvider', '')) =~ 'MICROSOFT.KEYVAULT/VAULTS'
    | extend Operation = tostring(column_ifexists('OperationName', '')), Result = tostring(column_ifexists('ResultType', '')), UserPrincipalName = tostring(column_ifexists('identity_claim_upn_s', '')), AppId = tostring(column_ifexists('identity_claim_appid_g', '')), Caller = tostring(column_ifexists('Caller', '')), CallerIPAddress = tostring(column_ifexists('CallerIPAddress', '')), CallerIpAddress = tostring(column_ifexists('CallerIpAddress', ''))
    | where Operation has_any (SensitiveOperations)
    | extend AccountName = case(isnotempty(UserPrincipalName), UserPrincipalName, isnotempty(AppId), AppId, isnotempty(Caller), Caller, 'Unknown'), IPAddress = case(isnotempty(CallerIPAddress), CallerIPAddress, isnotempty(CallerIpAddress), CallerIpAddress, 'Unknown'), VaultResource = tostring(column_ifexists('Resource', ''))
    | project TimeGenerated, AccountName, IPAddress, Operation, Result, VaultResource;
let VaultActivityEvents =
    AzureActivity
    | where TimeGenerated {TimeRange:query}
    | where tostring(column_ifexists('ResourceProviderValue', '')) =~ 'MICROSOFT.KEYVAULT'
    | extend Operation = tostring(column_ifexists('OperationNameValue', '')), Result = tostring(column_ifexists('ActivityStatusValue', '')), Caller = tostring(column_ifexists('Caller', '')), CallerIp = tostring(column_ifexists('CallerIpAddress', ''))
    | where Operation has_any (SensitiveOperations)
    | extend AccountName = iff(isnotempty(Caller), Caller, 'Unknown'), IPAddress = iff(isnotempty(CallerIp), CallerIp, 'Unknown'), VaultResource = tostring(column_ifexists('ResourceId', ''))
    | project TimeGenerated, AccountName, IPAddress, Operation, Result, VaultResource;
union isfuzzy=true VaultDiagnosticEvents, VaultActivityEvents
| summarize OperationCount = count(), VaultCount = dcount(VaultResource), OperationSet = make_set(Operation, 20), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by AccountName, IPAddress, TimeWindow = bin(TimeGenerated, Window)
| where OperationCount >= SecretOperationThreshold or VaultCount >= VaultThreshold or tostring(OperationSet) has_any ('SecretBackup', 'KeyBackup', 'CertificateBackup', 'secrets/backup', 'keys/backup', 'certificates/backup')
| extend TimeGenerated = LastSeen, Action = strcat('High-volume Key Vault sensitive object access: ', tostring(OperationCount), ' operations across ', tostring(VaultCount), ' vault resource(s).'), Severity = case(OperationCount >= 50 or VaultCount >= 3 or tostring(OperationSet) has_any ('SecretBackup', 'KeyBackup', 'CertificateBackup', 'secrets/backup', 'keys/backup', 'certificates/backup'), 'High', 'Medium')
| project TimeGenerated, AccountName, IPAddress, Action, Severity, OperationCount, VaultCount, OperationSet, FirstSeen, LastSeen
| order by TimeGenerated desc
